# Example 3: Environment-Based Configuration
import os

def create_app_memory():
    config = Config.fused()

    if os.getenv("ENVIRONMENT") == "production":
        config.memory_backend = MemoryBackend.HYBRID
    else:
        config.memory_backend = MemoryBackend.INMEMORY

    return await create_memory_backend(config)

# Development: ENVIRONMENT=development python app.py
# Production: ENVIRONMENT=production python app.py

